INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M205-17-D5', 'ct_ziel = if(ct_wert_zielorganismus == ''cryptosporidien'', ct_ecoli_basis * 500, ct_ecoli_basis)', ARRAY['ct_wert_zielorganismus','ct_ecoli_basis']::text[], 'ct_ziel', 'mg·min/l', '§4.3.2', 'Plan 3: ct-Zielwert für den Zielorganismus — Cryptosporidien-Oozysten: das Fünfhundertfache des E.-coli-Werts (bezüglich 99 % Reduktion), sonst der E.-coli-Basiswert; Abgleich ct_wert ≥ ct_ziel STAGED (m205-G-12).', 'imported_unverified', 'Wesentlich für eine ausreichende Desinfektionswirkung ist die Einhaltung einer wirksamen Kombination von Ozonkonzentration (c) und Einwirkzeit ( $t$ ) ( $c t$-Konzept). Das für eine definierte Reduktion der Keimzahl einzuhaltende Produkt beider Größen ergibt den $c t$-Wert in $\mathrm{mg} \cdot \mathrm{min} \cdot \mathrm{l}^{-1}$, der für verschiedene Mikroorganismen experimentell bestimmt wurde (Merkblatt DVGW W 225). Als besonders resistent gegen Ozon haben sich Protozoen-Dauerformen erwiesen. So übersteigt der $c t$-Wert für CryptosporidienOozysten den für Escherichia coli um ca. das Fünfhundertfache (bezüglich einer Reduktion der Keimzahl um 99 \%). Aufgrund der Reaktion von Ozon auch mit anderen, insbesondere organischen Wasserinhaltsstoffen, sowie der Milieuabhängigkeit ( pH -Wert, Temperatur) der Stabilität des Ozons hängen die erforderlichen Bedingungen von den Verhältnissen des Einzelfalles ab und müssen im Regelfall durch Vorversuche ermittelt werden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M205-17' AND s.code = 'DWA-M-205'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M205-21-D1', 'chlordosis_verletzungen = count_rows(chlorungsmittel, dosis_ok == 0)', ARRAY['chlorungsmittel']::text[], 'chlordosis_verletzungen', NULL, '§4.4.2', 'Plan 3: Chlorungsmittel, deren Dosis außerhalb des gedruckten Bereichs liegt (Chlorgas / Hypochlorit 1–20 mg/l freies Chlor; Chlordioxid 5–10 g/m³).', 'imported_unverified', 'Bei Anwendung von Chlorgas wird am Einsatzort eine Chlorlösung aus Chlorgas und Wasser hergestellt und dem Abwasser zudosiert (indirekte Chlorung). Chlorgasdosiergeräte (Bild 9) arbeiten nach dem VakuumInjektorprinzip. Die Regelung der Zugabe muss sowohl mengenproportional als auch entsprechend der Chlorzehrung (Restchlorgehalt) erfolgen. Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH -Bereich zwischen 6 und 8 eingehalten wird.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M205-21' AND s.code = 'DWA-M-205'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M205-24-D1', 'log_reduktion_mean = mean_rows(proben_desinfektion, log_red, c_out > 0)', ARRAY['proben_desinfektion']::text[], 'log_reduktion_mean', 'log10', '§2.1, §4.1.4.2', 'Plan 3: Mittel der je Probe berechneten Log-Reduktion log10(c_in / c_out) über die Proben mit c_out > 0 (c_out = 0 ist als Log-Reduktion nicht definiert — Nachweisgrenze eintragen); die statistische Einhaltungsregel ist nicht gedruckt (m205-F-1).', 'imported_unverified', 'Die Wirksamkeit der Abwasserdesinfektion ist durch den bestimmungsgemäßen Betrieb der eingesetzten Verfahrenstechnik nachzuweisen und am Auslauf der Kläranlage vor der Vermischung mit dem Gewässer zu überprüfen. Zur Bewertung der reduzierenden Wirkung werden die Konzentrationen der Leitorganismen im Zulauf unmittelbar vor sowie nach der Desinfektionsanlage bestimmt (mikrobiologischer Nachweis). Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. Entscheidend für die Bewertung des behandelten Wassers ist jedoch die erreichte Konzentration im Abwasser nach der Behandlung.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M205-24' AND s.code = 'DWA-M-205'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
